create table if not exists public.lineage_seed_reviews(unit_id uuid primary key references public.lineage_units(id) on delete restrict,source_id uuid not null references public.sources(id),review_status text not null default 'needs_review' check(review_status in ('needs_review','verified','disputed','rejected')),raw_source_path text not null,imported_at timestamptz not null default now(),verified_by uuid references auth.users(id),verified_at timestamptz,reviewer_note text,check(review_status<>'verified' or (verified_by is not null and verified_at is not null)));

alter table public.lineage_seed_reviews enable row level security;

revoke all on public.lineage_seed_reviews from anon, authenticated;

insert into public.tribes(id,name_ar,description) values(md5('alhazmi:tribe:v1')::uuid,'الحازمي','الحازم/الحازمي — تفرعات مصدرية مبدئية تحتاج مراجعة نسب مستقلة') on conflict(id) do nothing;

insert into public.sources(id,tribe_id,source_type,title,author,source_url,citation_text,confidentiality) values(md5('alhazmi:source:bnabar-139')::uuid,md5('alhazmi:tribe:v1')::uuid,'other','قبايل الخميس من العقاقرة من ضنا فريض من ضنا محمد','عبدالله بن عبار','https://www.bnabar.com/vb/showthread.php?t=139','مصدر مناقشة منشورة؛ لا يثبت قرابة أفراد دون مستندات','restricted') on conflict(id) do nothing;

